import{bt as e,n as t,ot as n,st as r}from"./chunks/framework.CxhjsvYc.js";var i=JSON.parse(`{"title":"Independent Pages Artifact and Run-Local Benchmark Plan","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/development/independent-pages-artifacts-plan.html"}],["meta",{"property":"og:title","content":"Independent Pages Artifact and Run-Local Benchmark Plan | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/development/independent-pages-artifacts-plan.html"}],["meta",{"name":"twitter:title","content":"Independent Pages Artifact and Run-Local Benchmark Plan | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"development/independent-pages-artifacts-plan.md","filePath":"development/independent-pages-artifacts-plan.md","lastUpdated":1793983524000}`),a={name:`development/independent-pages-artifacts-plan.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="independent-pages-artifact-and-run-local-benchmark-plan" tabindex="-1">Independent Pages Artifact and Run-Local Benchmark Plan <a class="header-anchor" href="#independent-pages-artifact-and-run-local-benchmark-plan" aria-label="Permalink to “Independent Pages Artifact and Run-Local Benchmark Plan”">​</a></h1><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to “Objective”">​</a></h2><p>Keep the calculator web application and documentation build/deployment independent. On every push to <code>main</code>, each benchmark-backed documentation page runs its own benchmark, and the docs build consumes the generated data from that exact workflow run. Benchmark result JSON is not committed back to the repository or published through data branches/PRs.</p><h2 id="target-architecture" tabindex="-1">Target architecture <a class="header-anchor" href="#target-architecture" aria-label="Permalink to “Target architecture”">​</a></h2><ol><li><strong>Web producer</strong> (<code>web-pages.yml</code>): watches web UI, shared runtime, strategy, schema and bank-data dependencies. It builds only the web component and publishes it to <code>pages-web-artifact</code>. It does not wait for documentation benchmarks.</li><li><strong>Scoped Range page benchmark</strong>: a dedicated job in <code>docs-pages.yml</code> runs <code>scripts/strategy-sensitivity.js</code>, validates 324 observations across 108 scenario points, and uploads the generated <code>results.json</code> as a short-lived workflow artifact.</li><li><strong>Absolute R+ page benchmark</strong>: a separate job runs <code>scripts/gaml-sensitivity.js</code>, validates the 15 parameter observations, and uploads <code>gaml-search-results.json</code> as a short-lived workflow artifact.</li><li><strong>Docs build</strong>: waits for both benchmark jobs, downloads both outputs into <code>docs/strategies/benchmarks/</code>, runs the combined dataset validator, and builds VitePress. The JSON exists in the build workspace and is included in the static docs output, but is never committed or pushed to a data branch.</li><li><strong>Docs producer</strong>: publishes only the completed docs component to <code>pages-docs-artifact</code>. If either benchmark, validation or the docs build fails, it does not update the docs artifact; the previously deployed docs remain live.</li><li><strong>Component artifact branches</strong>: web and docs publishers update only their own branch. Each has a separate non-cancelling publication concurrency group.</li><li><strong>Reusable Pages assembler</strong> (<code>pages.yml</code>): fetches the latest web and docs component branches or safe preserved baselines, assembles one complete site, validates its entry points and performs one atomic GitHub Pages deployment. It records the deployed component SHA pair and skips duplicate deployments.</li><li><strong>Preserved baselines</strong>: when an actual component artifact is missing during migration, the assembler can seed either baseline from the source SHA of the last successful Pages deployment. These baselines preserve currently live content; they are not benchmark outputs.</li><li><strong>No bypass or data PR</strong>: source <code>main</code> remains protected. The docs pipeline needs no pull-request write permission and does not create, merge or dispatch a timestamped data PR.</li></ol><h2 id="trigger-and-execution-rules" tabindex="-1">Trigger and execution rules <a class="header-anchor" href="#trigger-and-execution-rules" aria-label="Permalink to “Trigger and execution rules”">​</a></h2><ul><li><code>docs-pages.yml</code> runs on every push to <code>main</code> and on manual dispatch.</li><li>The Scoped Range and Absolute R+ page benchmark jobs are independent. The docs build requires both to succeed.</li><li>Each benchmark artifact is scoped to its workflow run and retained for one day. The build downloads artifacts from that same run; it cannot reuse results from another branch, run or commit.</li><li>The generated JSON is not committed to <code>main</code>, published to a timestamped data branch, or used to create a PR.</li><li>The web producer remains path-filtered to web/runtime dependencies and is not triggered by docs benchmark outputs.</li><li>The standalone strategy workflow remains available for feature/chore branch and PR validation; it must not duplicate the main docs-owned benchmark.</li><li>Each main push has its own concurrency key. Component publication and Pages deployment retain separate non-cancelling concurrency controls.</li><li>Before publishing docs, compare the source revision with current <code>main</code> for docs and benchmark dependencies. If those dependencies advanced, do not publish a stale build.</li><li>A failed benchmark or docs build leaves the prior docs artifact and live site untouched.</li></ul><h2 id="why-the-docs-build-is-a-single-downstream-job" tabindex="-1">Why the docs build is a single downstream job <a class="header-anchor" href="#why-the-docs-build-is-a-single-downstream-job" aria-label="Permalink to “Why the docs build is a single downstream job”">​</a></h2><p>The two pages have different benchmark workloads and produce separate data files. VitePress still builds one coherent documentation component, so the benchmark jobs remain independent while the final docs build waits for both outputs. This prevents either page from publishing a partial docs tree over the other page.</p><p>GitHub Pages itself publishes a complete site atomically. The independent component artifacts allow the web app to update without waiting for docs, and docs to update without rebuilding the web app.</p><h2 id="implementation-phases" tabindex="-1">Implementation phases <a class="header-anchor" href="#implementation-phases" aria-label="Permalink to “Implementation phases”">​</a></h2><ol><li>Map web/docs build dependencies and record the current combined deployment behavior.</li><li>Add isolated web and docs build scripts.</li><li>Split Scoped Range and Absolute R+ into independent page-specific benchmark jobs.</li><li>Pass generated JSON between jobs as short-lived run artifacts; remove fingerprint-based main reuse and timestamped data-PR publication from the docs path.</li><li>Build VitePress only after both benchmark outputs pass validation; publish docs independently.</li><li>Assemble latest web/docs components in the reusable Pages workflow.</li><li>Add workflow-contract tests and verify CI.</li></ol><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to “Acceptance criteria”">​</a></h2><ul><li>Every push to main runs the Scoped Range benchmark and the Absolute R+ benchmark independently.</li><li>The docs build consumes outputs from those exact two jobs in that exact run.</li><li>The complete dataset validator runs before VitePress build.</li><li>No benchmark result JSON is committed, pushed to a data branch, or submitted in a PR.</li><li>No workflow attempts to create/approve a PR using GITHUB_TOKEN.</li><li>A failed benchmark/build cannot replace previously deployed docs.</li><li>The web producer does not wait for benchmark execution.</li><li>Every Pages deployment assembles both latest components and validates the complete site.</li><li>No main-branch protection bypass is introduced.</li></ul><h2 id="delivery-status" tabindex="-1">Delivery status <a class="header-anchor" href="#delivery-status" aria-label="Permalink to “Delivery status”">​</a></h2><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-0" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-0"> Independent web and docs producers.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-1" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-1"> Separate Scoped Range and Absolute R+ benchmark jobs.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-2" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-2"> Run-local benchmark artifacts with one-day retention.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-3" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-3"> Docs build restores and validates both datasets before building.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-4" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-4"> Removed main docs workflow&#39;s timestamped data-PR creation/merge/dispatch path.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-5" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-5"> Reusable Pages assembler and independent component artifacts.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-6" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-6"> Workflow contract tests updated for the run-local benchmark architecture.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-7" checked="checked" disabled="disabled"><label class="task-list-item-label" for="task-item-7"> CI verification on the final PR head (Node.js 22 tests, syntax checks, web/docs build smoke tests, workflow YAML parsing, docs PR build, Dependency Review and CodeQL).</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-8" disabled="disabled"><label class="task-list-item-label" for="task-item-8"> Post-merge production verification of both benchmark jobs, docs artifact publication and Pages deployment.</label></li></ul>`,16)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};